package com.example.newapp;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.speech.tts.TextToSpeech;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.TextView;import com.google.zxing.integration.android.IntentIntegrator;import com.google.zxing.integration.android.IntentResult;import org.json.JSONObject;import java.text.DecimalFormat;import java.util.Locale;
public class EditProductPriceScreen extends Activity implements TextToSpeech.OnInitListener {
 private StoreManagementRepository repo;private TextView details,status;private EditText priceInput;private JSONObject product;private TextToSpeech tts;private boolean ttsReady;private final DecimalFormat money=new DecimalFormat("0.##");private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+0.5f);}
 @Override protected void onCreate(Bundle b){super.onCreate(b);repo=new StoreManagementRepository(this);tts=new TextToSpeech(this,this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(16),dp(16),dp(16));
 details=new TextView(this);details.setText("สแกนบาร์โค้ดสินค้า 1 รายการเพื่อเริ่มแก้ไขราคา");details.setTextSize(16);root.addView(details,new LinearLayout.LayoutParams(-1,-2));
 Button scan=new Button(this);scan.setText("สแกนบาร์โค้ดสินค้า");scan.setOnClickListener(v->{product=null;priceInput.setText("");priceInput.setEnabled(false);details.setText("กำลังรอสแกนบาร์โค้ด…");status.setText("");new IntentIntegrator(this).setPrompt("สแกนบาร์โค้ดสินค้า 1 รายการ").setBeepEnabled(true).setOrientationLocked(true).initiateScan();});root.addView(scan);
 TextView label=new TextView(this);label.setText("ราคาขายใหม่");root.addView(label);priceInput=new EditText(this);priceInput.setSingleLine(true);priceInput.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);priceInput.setHint("กรอกราคาขายใหม่");priceInput.setEnabled(false);root.addView(priceInput);
 Button save=new Button(this);save.setText("ยืนยันและบันทึกราคา");save.setOnClickListener(v->savePrice());root.addView(save);status=new TextView(this);root.addView(status);Button back=new Button(this);back.setText("กลับ");back.setOnClickListener(v->finish());root.addView(back);setContentView(root);}
 @Override public void onInit(int result){if(result==TextToSpeech.SUCCESS){int l=tts.setLanguage(new Locale("th","TH"));ttsReady=l!=TextToSpeech.LANG_MISSING_DATA&&l!=TextToSpeech.LANG_NOT_SUPPORTED;}}
 @Override protected void onActivityResult(int req,int res,Intent data){IntentResult scan=IntentIntegrator.parseActivityResult(req,res,data);if(scan!=null){String code=scan.getContents();if(code==null||code.trim().isEmpty()){status.setText("ยกเลิกการสแกน");return;}JSONObject found=repo.findProductByBarcode(code);if(found==null){product=null;priceInput.setText("");priceInput.setEnabled(false);details.setText("ไม่พบสินค้าบาร์โค้ด: "+code);status.setText("ไม่พบสินค้าในฐานข้อมูลกลาง");return;}
 double old=repo.price(found);if(repo.productName(found).trim().isEmpty()||!Double.isFinite(old)){product=null;priceInput.setEnabled(false);details.setText("ข้อมูลสินค้าไม่ครบ จึงไม่อนุญาตให้แก้ไข");status.setText("รายการต้องมีฟิลด์ name, barcode และ price ใน DataHub");return;}
 product=found;details.setText("ชื่อสินค้า: "+repo.productName(found)+"\nบาร์โค้ด: "+repo.barcode(found)+"\nราคาปัจจุบัน: "+money.format(old)+" บาท");priceInput.setText(money.format(old));priceInput.setEnabled(true);status.setText("ตรวจสอบชื่อและบาร์โค้ดก่อนบันทึก");if(ttsReady)tts.speak(repo.productName(found),TextToSpeech.QUEUE_FLUSH,null,"product-name");return;}super.onActivityResult(req,res,data);}
 private void savePrice(){if(product==null){status.setText("กรุณาสแกนสินค้าที่พบในฐานข้อมูลก่อน");return;}final double n;try{String raw=priceInput.getText().toString().trim().replace(',','.');if(raw.isEmpty())throw new NumberFormatException();n=Double.parseDouble(raw);if(!Double.isFinite(n)||n<0)throw new NumberFormatException();}catch(NumberFormatException e){status.setText("กรุณากรอกราคาเป็นตัวเลขที่ถูกต้องและไม่ติดลบ");return;}
 double old=repo.price(product);if(Double.compare(old,n)==0){status.setText("ราคาใหม่เท่ากับราคาเดิม ไม่มีการเปลี่ยนแปลง");return;}String name=repo.productName(product),code=repo.barcode(product);if(!repo.updatePrice(product,n)){status.setText("บันทึกไม่สำเร็จ: ข้อมูลสินค้าอาจเปลี่ยนไปแล้วหรือฐานข้อมูลไม่พร้อม กรุณาสแกนใหม่");product=null;priceInput.setEnabled(false);return;}
 String msg="เปลี่ยนราคา "+name+" จาก "+money.format(old)+" เป็น "+money.format(n)+" บาท";status.setText("บันทึกราคาและประวัติสำเร็จ\n"+msg);details.setText("ชื่อสินค้า: "+name+"\nบาร์โค้ด: "+code+"\nราคาเดิม: "+money.format(old)+" บาท\nราคาใหม่: "+money.format(n)+" บาท");PriceChangeNotifier.notifySaved(this,msg);product=null;priceInput.setEnabled(false);}
 @Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}
}
